const TZ = 'Europe/Rome';

/* ---------- dati ---------- */

const tutte = [
  ...$('Leggi Transazioni').all().map(i => i.json),
].filter(r => r.data_evento &&
              !['eliminata', 'attesa'].includes(String(r.stato)));

const attese = $('Leggi Transazioni').all().map(i => i.json)
  .filter(r => String(r.stato) === 'attesa' && r.data_evento);

const budget = {};
$('Leggi Categorie').all().map(i => i.json).forEach(c => {
  if (c.categoria) budget[c.categoria] = Number(c.budget_mensile) || 0;
});

/* ---------- date ---------- */

const oggiStr = new Date().toLocaleDateString('sv-SE', { timeZone: TZ }); // YYYY-MM-DD
const oggi = new Date(oggiStr + 'T12:00:00');
const giornoMese = oggi.getDate();
const giornoSett = oggi.getDay();           // 0 dom, 1 lun

const iso = (d) => d.toISOString().slice(0, 10);
const menoGiorni = (d, n) => { const x = new Date(d); x.setDate(x.getDate() - n); return x; };
const meseDi = (d) => iso(d).slice(0, 7);

/* ---------- utilita' ---------- */

const eur = (n) => (Math.round(n * 100) / 100).toFixed(2).replace('.', ',') + ' €';
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

function somma(righe, tipo) {
  return righe.filter(r => String(r.tipo) === tipo)
              .reduce((s, r) => s + (Number(r.importo) || 0), 0);
}

function nelPeriodo(prefisso) {
  return tutte.filter(r => String(r.data_evento).startsWith(prefisso));
}

function fraDate(da, a) {
  return tutte.filter(r => {
    const d = String(r.data_evento).slice(0, 10);
    return d >= da && d <= a;
  });
}

function perCategoria(righe) {
  const m = {};
  righe.filter(r => String(r.tipo) === 'spesa').forEach(r => {
    const c = String(r.categoria || 'Senza categoria');
    m[c] = (m[c] || 0) + (Number(r.importo) || 0);
  });
  return m;
}

function mediana(v) {
  if (!v.length) return 0;
  const s = v.slice().sort((a, b) => a - b);
  const h = Math.floor(s.length / 2);
  return s.length % 2 ? s[h] : (s[h - 1] + s[h]) / 2;
}

function variazione(ora, prima) {
  if (!prima) return '';
  const p = Math.round((ora - prima) / prima * 100);
  if (Math.abs(p) < 3) return ' (in linea)';
  return ' (' + (p > 0 ? '+' : '') + p + '%)';
}

/* ---------- stato fonti, usato nel settimanale ---------- */

function statoFonti() {
  const fonti = ['push', 'gmail', 'outlook', 'telegram', 'app'];
  const out = [];
  for (const f of fonti) {
    const righe = tutte.filter(r => String(r.fonte) === f && r.data_inserimento);
    if (!righe.length) continue;
    const ultima = righe.map(r => String(r.data_inserimento)).sort().pop();
    const gg = Math.floor((oggi - new Date(ultima)) / 86400000);
    out.push(f + ' ' + (gg <= 1 ? 'oggi' : gg + 'g'));
  }
  return out.join(' · ');
}

/* ============================================================
   REPORT SETTIMANALE — lunedi'
   ============================================================ */

function settimanale() {
  const da = iso(menoGiorni(oggi, 7));
  const a = iso(menoGiorni(oggi, 1));
  const righe = fraDate(da, a);
  const uscite = somma(righe, 'spesa');

  // Media delle quattro settimane precedenti: dice se questa e' fuori scala.
  const precedenti = [];
  for (let k = 2; k <= 5; k++) {
    precedenti.push(somma(fraDate(iso(menoGiorni(oggi, 7 * k)),
                                  iso(menoGiorni(oggi, 7 * (k - 1) + 1))), 'spesa'));
  }
  const media4 = precedenti.reduce((s, v) => s + v, 0) / (precedenti.length || 1);

  const cat = perCategoria(righe);
  const top = Object.keys(cat).sort((x, y) => cat[y] - cat[x]).slice(0, 4);

  // Andamento del mese in corso rispetto al budget, proporzionato ai giorni.
  const mese = nelPeriodo(meseDi(oggi));
  const catMese = perCategoria(mese);
  const giorniMese = new Date(oggi.getFullYear(), oggi.getMonth() + 1, 0).getDate();
  const quota = giornoMese / giorniMese;

  const sforati = Object.keys(catMese)
    .filter(c => budget[c] > 0 && catMese[c] > budget[c] * quota * 1.15)
    .sort((x, y) => (catMese[y] / budget[y]) - (catMese[x] / budget[x]))
    .slice(0, 4);

  const prossime = attese
    .filter(r => String(r.data_evento) <= iso(menoGiorni(oggi, -7)))
    .sort((x, y) => String(x.data_evento).localeCompare(String(y.data_evento)));

  const daVer = $('Leggi Transazioni').all().map(i => i.json)
    .filter(r => String(r.stato) === 'da_verificare').length;

  let t = '<b>Settimana ' + da.slice(8) + '–' + a.slice(8) + '/' + a.slice(5, 7) + '</b><br>';
  t += 'Spese: <b>' + eur(uscite) + '</b>' + variazione(uscite, media4) + '<br>';
  t += '<i>media 4 settimane: ' + eur(media4) + '</i><br>';

  if (top.length) {
    t += '<br><pre>';
    for (const c of top) t += esc(c.slice(0, 20).padEnd(21)) + eur(cat[c]).padStart(10) + '\n';
    t += '</pre>';
  }

  if (sforati.length) {
    t += '<br><b>Oltre il ritmo del budget</b><br>';
    for (const c of sforati) {
      t += '• ' + esc(c) + ': ' + eur(catMese[c]) + ' su ' + eur(budget[c]) + '<br>';
    }
  }

  if (prossime.length) {
    t += '<br><b>In arrivo</b><br>';
    for (const r of prossime.slice(0, 5)) {
      t += '• ' + String(r.data_evento).slice(8) + '/' + String(r.data_evento).slice(5, 7) +
           ' ' + esc(r.esercente || r.note || r.categoria) + ' ' + eur(Number(r.importo)) + '<br>';
    }
  }

  if (daVer) t += '<br>' + daVer + ' movimenti da verificare<br>';

  t += '<br><i>Fonti: ' + esc(statoFonti()) + '</i>';
  return t;
}

/* ============================================================
   REPORT MENSILE — il primo del mese, sul mese appena chiuso
   ============================================================ */

function mensile() {
  const primo = new Date(oggi.getFullYear(), oggi.getMonth(), 1);
  const chiuso = meseDi(menoGiorni(primo, 1));                 // mese precedente
  const prima = meseDi(menoGiorni(new Date(chiuso + '-15'), 30));
  const annoPrima = (Number(chiuso.slice(0, 4)) - 1) + chiuso.slice(4);

  const righe = nelPeriodo(chiuso);
  const uscite = somma(righe, 'spesa');
  const entrate = somma(righe, 'entrata');

  const usPrima = somma(nelPeriodo(prima), 'spesa');
  const usAnno = somma(nelPeriodo(annoPrima), 'spesa');

  const cat = perCategoria(righe);

  // Mediana della stessa categoria negli ultimi 12 mesi: identifica cosa e'
  // fuori linea rispetto alle tue abitudini, non rispetto al budget.
  const mesiStorici = [];
  for (let k = 1; k <= 12; k++) {
    mesiStorici.push(meseDi(menoGiorni(new Date(chiuso + '-15'), 30 * k)));
  }
  const storiche = {};
  for (const c of Object.keys(cat)) {
    storiche[c] = mediana(mesiStorici.map(m => perCategoria(nelPeriodo(m))[c] || 0));
  }

  const fuoriLinea = Object.keys(cat)
    .filter(c => storiche[c] > 20 && Math.abs(cat[c] - storiche[c]) / storiche[c] > 0.3)
    .sort((x, y) => Math.abs(cat[y] - storiche[y]) - Math.abs(cat[x] - storiche[x]))
    .slice(0, 4);

  const maggiore = righe.filter(r => String(r.tipo) === 'spesa')
    .sort((x, y) => Number(y.importo) - Number(x.importo))[0];

  const gMese = new Date(Number(chiuso.slice(0, 4)), Number(chiuso.slice(5, 7)), 0).getDate();

  // Da inizio anno, confrontato con lo stesso intervallo dell'anno prima.
  const anno = chiuso.slice(0, 4);
  const ytd = somma(tutte.filter(r => {
    const d = String(r.data_evento);
    return d >= anno + '-01-01' && d <= chiuso + '-31';
  }), 'spesa');
  const ytdPrima = somma(tutte.filter(r => {
    const d = String(r.data_evento);
    const a1 = String(Number(anno) - 1);
    return d >= a1 + '-01-01' && d <= a1 + chiuso.slice(4) + '-31';
  }), 'spesa');

  let t = '<b>Chiusura ' + chiuso + '</b><br>';
  t += 'Entrate: ' + eur(entrate) + '<br>';
  t += 'Uscite: <b>' + eur(uscite) + '</b>' + variazione(uscite, usPrima) + '<br>';
  t += 'Saldo: <b>' + eur(entrate - uscite) + '</b><br>';
  t += '<i>media ' + eur(uscite / gMese) + ' al giorno</i><br>';
  if (usAnno) t += '<i>stesso mese ' + annoPrima.slice(0, 4) + ': ' + eur(usAnno) + '</i><br>';

  const ordinate = Object.keys(cat).sort((x, y) => cat[y] - cat[x]).slice(0, 10);
  t += '<br><pre>';
  for (const c of ordinate) {
    const b = budget[c] > 0 ? eur(budget[c]).replace(' €', '') : '—';
    t += esc(c.slice(0, 17).padEnd(18)) + eur(cat[c]).replace(' €', '').padStart(9) +
         ' /' + b.padStart(8) + '\n';
  }
  t += '</pre>';

  if (fuoriLinea.length) {
    t += '<br><b>Fuori dalle abitudini</b><br>';
    for (const c of fuoriLinea) {
      const d = cat[c] - storiche[c];
      t += '• ' + esc(c) + ': ' + eur(cat[c]) + ', solito ' + eur(storiche[c]) +
           ' (' + (d > 0 ? '+' : '') + eur(d) + ')<br>';
    }
  }

  if (maggiore) {
    t += '<br>Spesa maggiore: ' + eur(Number(maggiore.importo)) + ' — ' +
         esc(maggiore.esercente || maggiore.note || maggiore.categoria) + '<br>';
  }

  if (ytdPrima) {
    t += '<br>Da inizio anno: ' + eur(ytd) + ' contro ' + eur(ytdPrima) +
         variazione(ytd, ytdPrima);
  }

  return t;
}

/* ---------- quale report oggi ---------- */

let testo = null;
if (giornoMese === 1) testo = mensile();        // il mensile ha la precedenza
else if (giornoSett === 1) testo = settimanale();

if (!testo) return [];

return { json: {
    text: (testo.slice(0, 4000)),      // Telegram si ferma a 4096
}};
